CREATE TABLE IF NOT EXISTS legacy_opening_creditor_reclassification_evidence (
  document_id INTEGER PRIMARY KEY REFERENCES non_cash_balance_correction_evidence(document_id),
  opening_journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),
  opening_journal_line_id INTEGER NOT NULL REFERENCES journal_lines(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER IF NOT EXISTS legacy_opening_creditor_reclassification_evidence_guard_insert BEFORE INSERT ON legacy_opening_creditor_reclassification_evidence WHEN NOT EXISTS (SELECT 1 FROM documents d JOIN non_cash_balance_correction_evidence ncc ON ncc.document_id=d.id JOIN opening_balances marker ON marker.journal_entry_id=NEW.opening_journal_entry_id JOIN journal_entries opening ON opening.id=marker.journal_entry_id AND opening.status='posted' JOIN journal_lines line ON line.id=NEW.opening_journal_line_id AND line.journal_entry_id=opening.id JOIN accounts account ON account.id=line.account_id JOIN account_role_mappings role ON role.account_no=account.account_no AND role.role='creditors' AND role.status='confirmed' WHERE d.id=NEW.document_id AND json_extract(d.payload_json,'$.internalVoucherKind')='legacy_opening_creditor_reclassification' AND line.debit_amount=0 AND line.credit_amount>0) BEGIN SELECT RAISE(ABORT, 'legacy opening creditor reclassification requires one exact immutable primobalance creditor line'); END;
CREATE TRIGGER IF NOT EXISTS legacy_opening_creditor_reclassification_evidence_no_update BEFORE UPDATE ON legacy_opening_creditor_reclassification_evidence BEGIN SELECT RAISE(ABORT, 'legacy opening creditor reclassification evidence is append-only'); END;
CREATE TRIGGER IF NOT EXISTS legacy_opening_creditor_reclassification_evidence_no_delete BEFORE DELETE ON legacy_opening_creditor_reclassification_evidence BEGIN SELECT RAISE(ABORT, 'legacy opening creditor reclassification evidence is append-only'); END;
